// Authoring-only definitions. generate-coding-bank.mjs freezes inputs, keys and programs offline.
export const definitions={};
const add=(module,id,difficulty,prompt,input,output,inputs,oracle,source,language='python',skills,competence=0)=>{
 (definitions[module]??=[]).push({id,difficulty,prompt,input,output,inputs,oracle,source,language,skills,competence});
};
const py=(module,id,d,prompt,input,output,inputs,oracle,expr,skills,c=0)=>add(module,id,d,prompt,input,output,inputs,oracle,'import json,sys,math,collections,itertools\ndata=json.load(sys.stdin)\nprint(json.dumps('+expr+',ensure_ascii=False,allow_nan=False))','python',skills,c);
const pp=(module,id,d,prompt,input,output,inputs,oracle,body,skills,c=0)=>add(module,id,d,prompt,input,output,inputs,oracle,'import json,sys,math,collections,itertools\ndata=json.load(sys.stdin)\n'+body,'python',skills,c);
const js=(module,id,d,prompt,input,output,inputs,oracle,expr,skills,c=0,language='javascript')=>add(module,id,d,prompt,input,output,inputs,oracle,'const data=JSON.parse(require("node:fs").readFileSync(0,"utf8"));\nconsole.log(JSON.stringify('+expr+'));',language,skills,c);
const jp=(module,id,d,prompt,input,output,inputs,oracle,body,skills,c=0,language='javascript')=>add(module,id,d,prompt,input,output,inputs,oracle,'const data=JSON.parse(require("node:fs").readFileSync(0,"utf8"));\n'+body,language,skills,c);
const arrs=[[],[0],[3,-2,3,0,-2],[9,1,5,2],[-4,-1,-4,8]];
const strings=['','a','abba','a b a','Hello, world!'];
const sum=a=>a.reduce((s,x)=>s+x,0);
const sorted=a=>[...a].sort((a,b)=>a-b);
const round=x=>Math.round((x+Number.EPSILON)*1e4)/1e4;
// Eight independently authored families at each difficulty, rather than changing numbers in old tasks.
py('python','even-position-sum',1,'Сложите элементы на чётных индексах (0,2,4,...). Пустая сумма равна 0.','Массив целых чисел длины 0..200.','Целое число.',arrs,a=>sum(a.filter((_,i)=>i%2===0)),'sum(data[::2])',null,1);
py('python','stable-nonzero',1,'Удалите нули, сохранив порядок остальных элементов.','Массив целых чисел длины 0..200.','Массив целых чисел.',arrs,a=>a.filter(x=>x!==0),'[x for x in data if x!=0]',null,1);
py('python','adjacent-differences',1,'Верните разности a[i+1]-a[i]. Для длины меньше 2 верните [].','Массив целых чисел длины 0..200.','Массив разностей.',arrs,a=>a.slice(1).map((x,i)=>x-a[i]),'[b-a for a,b in zip(data,data[1:])]',null,1);
py('python','word-lengths',1,'Разбейте строку по пробельным символам и верните длины слов. Пунктуация входит в слово.','JSON-строка из ASCII, длина 0..500.','Массив длин.',strings,s=>s.trim()?s.trim().split(/\s+/).map(x=>x.length):[],'[len(s) for s in data.split()]',null,0);
py('python','first-maximum-index',1,'Верните индекс первого максимального элемента, для пустого массива null.','Массив целых чисел длины 0..200.','Индекс или null.',arrs,a=>a.length?a.indexOf(Math.max(...a)):null,'data.index(max(data)) if data else None',null,1);
py('python','clamp-values',1,'Ограничьте каждое число диапазоном [low,high]. Границы включены.','Объект {values:[целое],low:целое,high:целое}, low<=high.','Массив чисел.',[...arrs].map((values,i)=>({values,low:-i,high:i})),x=>x.values.map(v=>Math.min(x.high,Math.max(x.low,v))),'[min(data["high"],max(data["low"],v)) for v in data["values"]]',null,0);
py('python','safe-integer-fields',1,'У каждого объекта прочитайте value. Сложите только JSON-целые числа; boolean, null, строки и отсутствующее поле игнорируются.','Массив объектов. Числа конечные, безопасные для целочисленной арифметики.','Сумма.',[[],[{}],[{value:2},{value:true},{value:'3'}],[{value:-2},{value:1.5},{value:null}],[{value:0},{value:7}]],a=>sum(a.map(x=>x.value).filter(x=>typeof x==='number'&&Number.isInteger(x))),'sum(x["value"] for x in data if type(x.get("value")) in (int,float) and x["value"]==int(x["value"]))',null,2);
py('python','pairs-to-last-value',1,'Пары [key,value] образуют словарь. При повторе ключа сохраняется последнее значение.','Массив пар, key — строка, value — JSON-значение.','JSON-объект.',[[],[['a',1]],[['a',1],['a',2]],[['x',null],['y',false]],[['__proto__',3],['toString',4]]],a=>Object.fromEntries(a),'dict(data)',null,1);
py('python','prefix-sums',2,'Верните накопительные суммы, включая текущий элемент. Для [] верните [].','Массив целых чисел длины 0..200.','Массив сумм.',arrs,a=>a.map((_,i)=>sum(a.slice(0,i+1))),'list(itertools.accumulate(data))',null,1);
py('python','chunk-list',2,'Разбейте список на последовательные части размера size; последняя может быть короче.','Объект {values:[JSON-значение],size:целое 1..100}.','Массив частей.',arrs.map((values,i)=>({values,size:i%3+1})),x=>Array.from({length:Math.ceil(x.values.length/x.size)},(_,i)=>x.values.slice(i*x.size,(i+1)*x.size)),'[data["values"][i:i+data["size"]] for i in range(0,len(data["values"]),data["size"])]',null,1);
py('python','distinct-intersection',2,'Верните пересечение a и b без повторов по возрастанию.','Объект {a:[целое],b:[целое]}.','Массив целых чисел.',arrs.map((a,i)=>({a,b:arrs[(i+2)%5]})),x=>sorted([...new Set(x.a.filter(v=>x.b.includes(v)))]),'sorted(set(data["a"]) & set(data["b"]))',null,1);
py('python','rotate-left',2,'Циклически сдвиньте массив влево на k позиций. k может быть отрицательным. Пустой массив остаётся пустым.','Объект {values:[целое],k:целое}.','Массив.',arrs.map((values,i)=>({values,k:[0,4,-1,9,-7][i]})),x=>{if(!x.values.length)return [];const k=((x.k%x.values.length)+x.values.length)%x.values.length;return [...x.values.slice(k),...x.values.slice(0,k)];},'(lambda a,k: a[k:]+a[:k])(data["values"],data["k"]%len(data["values"])) if data["values"] else []',null,0);
py('python','group-record-identifiers',2,'Сгруппируйте id по строковому group. В каждой группе сохраняйте входной порядок.','Массив {id:целое,group:строка}.','Объект group -> массив id.',[[],[{id:1,group:'a'}],[{id:1,group:'b'},{id:2,group:'a'},{id:3,group:'b'}],[{id:0,group:'__proto__'}],[{id:2,group:''},{id:2,group:''}]],a=>Object.fromEntries([...new Set(a.map(x=>x.group))].map(g=>[g,a.filter(x=>x.group===g).map(x=>x.id)])),'{g:[x["id"] for x in data if x["group"]==g] for g in dict.fromkeys(x["group"] for x in data)}',null,1);
py('python','multiset-subtraction',2,'Для каждого числа a удалите столько первых вхождений, сколько оно встречается в b. Порядок оставшихся элементов сохраняется.','Объект {a:[целое],b:[целое]}.','Массив.',[{a:[],b:[]},{a:[1,1,2],b:[1]},{a:[1,2,1],b:[1,1,1]},{a:[0,-1,0],b:[0]},{a:[3,2],b:[]}],x=>{const b=[...x.b];return x.a.filter(v=>{const i=b.indexOf(v);if(i<0)return true;b.splice(i,1);return false;});},'(lambda counts: [x for x in data["a"] if not (counts[x]>0 and not counts.subtract([x]))])(collections.Counter(data["b"]))',null,1);
py('python','sort-records-with-ties',2,'Отсортируйте записи по score по убыванию, затем id по возрастанию. Верните id.','Массив {id:уникальное целое,score:целое}.','Массив id.',[[],[{id:1,score:0}],[{id:3,score:2},{id:1,score:2},{id:2,score:3}],[{id:1,score:-3},{id:2,score:0}],[{id:9,score:1},{id:0,score:1}]],a=>[...a].sort((a,b)=>b.score-a.score||a.id-b.id).map(x=>x.id),'[x["id"] for x in sorted(data,key=lambda x:(-x["score"],x["id"]))]',null,1);
py('python','transpose-rectangular',2,'Транспонируйте прямоугольную матрицу. Для [] и матрицы без столбцов верните [].','Массив равнодлинных массивов целых чисел.','Матрица.',[[],[[]],[[1]],[[1,2],[3,4]],[[1,2,3],[4,5,6]]],a=>a.length&&a[0].length?a[0].map((_,i)=>a.map(r=>r[i])):[],'[list(col) for col in zip(*data)]',null,1);
pp('python','balanced-depth',3,'Строка содержит только ( и ). Верните максимальную глубину вложенности, либо -1 для некорректной строки.','JSON-строка длины 0..300.','Целое число.',['','()','(()())','())(','((('],s=>{let n=0,m=0;for(const c of s){n+=c==='('?1:-1;if(n<0)return -1;m=Math.max(m,n);}return n?-1:m;},'depth=0\nmaximum=0\nok=True\nfor c in data:\n    depth+=1 if c=="(" else -1\n    maximum=max(maximum,depth)\n    if depth<0: ok=False\nprint(json.dumps(maximum if ok and depth==0 else -1))',null,2);
py('python','sliding-window-sums',3,'Для каждого последовательного окна размера k верните его сумму. Если k больше длины, верните [].','Объект {values:[целое],k:положительное целое}.','Массив сумм.',arrs.map((values,i)=>({values,k:[1,2,2,4,3][i]})),x=>Array.from({length:Math.max(0,x.values.length-x.k+1)},(_,i)=>sum(x.values.slice(i,i+x.k))),'[sum(data["values"][i:i+data["k"]]) for i in range(len(data["values"])-data["k"]+1)]',null,1);
py('python','longest-distinct-segment',3,'Верните длину самого длинного непрерывного фрагмента без повторов.','Массив целых чисел длины 0..200.','Целое число.',arrs,a=>{let m=0;for(let i=0;i<a.length;i++){const s=new Set();for(let j=i;j<a.length&&!s.has(a[j]);j++){s.add(a[j]);m=Math.max(m,s.size);}}return m;},'max((j-i for i in range(len(data)+1) for j in range(i,len(data)+1) if len(set(data[i:j]))==j-i),default=0)',null,1);
py('python','minimal-covering-window',3,'Найдите минимальную длину непрерывного фрагмента, содержащего все различные числа из required. Если required пуст или покрытие невозможно, верните 0.','Объект {values:[целое],required:[целое]}, длины до 80.','Целое число.',[{values:[],required:[]},{values:[1,2,3],required:[2]},{values:[1,2,1,3],required:[1,3]},{values:[1,1],required:[2]},{values:[1,2],required:[1,1,2]}],x=>{let best=Infinity;const r=new Set(x.required);if(!r.size)return 0;for(let i=0;i<x.values.length;i++)for(let j=i+1;j<=x.values.length;j++)if([...r].every(v=>x.values.slice(i,j).includes(v)))best=Math.min(best,j-i);return isFinite(best)?best:0;},'min((j-i for i in range(len(data["values"])+1) for j in range(i+1,len(data["values"])+1) if set(data["required"]).issubset(data["values"][i:j])),default=0) if data["required"] else 0',null,1);
pp('python','dependency-cycle',3,'Проверьте наличие цикла в ориентированном графе. Вершины — целые числа; edges содержат пары [from,to], включая петли.','Объект {nodes:[уникальное целое],edges:[[целое,целое]]}; концы рёбер входят в nodes.','true при цикле, иначе false.',[{nodes:[],edges:[]},{nodes:[1],edges:[[1,1]]},{nodes:[1,2],edges:[[1,2]]},{nodes:[1,2,3],edges:[[1,2],[2,3],[3,1]]},{nodes:[1,2,3],edges:[[1,3],[2,3]]}],x=>{const reach=new Map(x.nodes.map(n=>[n,new Set()]));for(const[a,b]of x.edges)reach.get(a).add(b);for(const k of x.nodes)for(const i of x.nodes)for(const j of x.nodes)if(reach.get(i).has(k)&&reach.get(k).has(j))reach.get(i).add(j);return x.nodes.some(n=>reach.get(n).has(n));},'indegree={n:0 for n in data["nodes"]}\nadj={n:[] for n in data["nodes"]}\nfor a,b in data["edges"]:\n    adj[a].append(b); indegree[b]+=1\nqueue=collections.deque(n for n in indegree if indegree[n]==0)\nvisited=0\nwhile queue:\n    n=queue.popleft(); visited+=1\n    for v in adj[n]:\n        indegree[v]-=1\n        if indegree[v]==0: queue.append(v)\nprint(json.dumps(visited!=len(indegree)))',null,2);
pp('python','cache-lru',3,'Смоделируйте LRU-кеш capacity: каждое обращение переносит ключ в конец; новый ключ при полном кеше вытесняет самый давно использованный. Верните ключи от старого к новому.','Объект {capacity:целое 1..20,keys:[строка]}.','Массив строк.',[{capacity:1,keys:[]},{capacity:1,keys:['a','b','a']},{capacity:2,keys:['a','b','a','c']},{capacity:3,keys:['x','x']},{capacity:2,keys:['__proto__','a','b']}],x=>{let a=[];for(const k of x.keys){a=a.filter(v=>v!==k);a.push(k);if(a.length>x.capacity)a.shift();}return a;},'cache=collections.OrderedDict()\nfor key in data["keys"]:\n    cache.pop(key,None); cache[key]=True\n    if len(cache)>data["capacity"]: cache.popitem(last=False)\nprint(json.dumps(list(cache)))',null,2);
py('python','sparse-vector-dot',3,'Векторы представлены парами [index,value]; повтор индекса означает суммирование вкладов. Вычислите скалярное произведение.','Объект {a:[[неотрицательное целое,целое]],b:[[неотрицательное целое,целое]]}.','Целое число.',[{a:[],b:[]},{a:[[0,2]],b:[[0,3]]},{a:[[1,2],[1,-1]],b:[[1,5]]},{a:[[0,1]],b:[[1,3]]},{a:[[2,-2],[4,3]],b:[[2,4],[4,-1]]}],x=>sum(x.a.flatMap(([i,a])=>x.b.filter(([j])=>i===j).map(([,b])=>a*b))),'sum(a*b for i,a in data["a"] for j,b in data["b"] if i==j)',null,1);
py('python','interval-overlap-peak',3,'Полуоткрытые интервалы [start,end) имеют start<end. Верните максимальное число одновременно активных интервалов. Касание границ не даёт пересечения.','Массив пар целых чисел, длина до 100.','Целое число.',[[],[[0,1]],[[0,2],[2,3]],[[0,3],[1,4],[2,5]],[[1,2],[1,2],[1,2]]],a=>Math.max(0,...a.flat().map(t=>a.filter(([l,r])=>l<=t&&t<r).length)),'max((sum(a<=t<b for a,b in data) for t in {x for pair in data for x in pair}),default=0)',null,2);
