js('javascript','safe-own-property',1,'Проверьте наличие собственного поля key, даже если его значение null. Поля прототипа не считаются.','Объект {object:JSON-объект,key:строка}.','true или false.',[{object:{},key:'toString'},{object:{a:null},key:'a'},{object:{a:1},key:'b'},{object:JSON.parse('{"__proto__":0}'),key:'__proto__'},{object:{hasOwnProperty:false},key:'hasOwnProperty'}],x=>Object.hasOwn(x.object,x.key),'Object.hasOwn(data.object,data.key)',null,0);
