js('javascript','safe-nested-path',2,'Пройдите по path (массив строковых ключей). Если нет собственного поля или промежуточное значение null/не объект, верните null. Пустой path возвращает исходное значение.','Объект {value:JSON-значение,path:[строка]}.','Значение или null.',[{value:{a:{b:0}},path:['a','b']},{value:null,path:[]},{value:{},path:['toString']},{value:{a:null},path:['a','x']},{value:JSON.parse('{"__proto__":{"x":4}}'),path:['__proto__','x']}],x=>x.path.reduce((v,k)=>v!==null&&typeof v==='object'&&Object.hasOwn(v,k)?v[k]:null,x.value),'data.path.reduce((v,k)=>v!==null&&typeof v==="object"&&Object.hasOwn(v,k)?v[k]:null,data.value)',null,0);
js('javascript','normalize-keyed-cache',2,'Нормализуйте записи в {ids,entities}. ids — уникальные id по первой встрече, entities хранит последнюю запись каждого id.','Массив {id:строка,value:JSON-значение}.','Объект {ids:[строка],entities:объект}.',[[],[{id:'a',value:1}],[{id:'a',value:1},{id:'b',value:2},{id:'a',value:3}],[{id:'__proto__',value:0}],[{id:'',value:false}]],a=>({ids:[...new Set(a.map(r=>r.id))],entities:Object.fromEntries(a.map(r=>[r.id,r]))}),'({ids:[...new Set(data.map(r=>r.id))],entities:Object.fromEntries(data.map(r=>[r.id,r]))})',null,2);
jp('javascript','latest-request-reducer',3,'События start(id) назначают текущий запрос; finish(id,value) применяются только к текущему. Верните {requestId,value}, начальные значения null.','Массив {type:"start"|"finish",id:целое,value?:JSON-значение}.','Объект.',[[],[{type:'finish',id:1,value:2}],[{type:'start',id:1},{type:'start',id:2},{type:'finish',id:1,value:9}],[{type:'start',id:1},{type:'finish',id:1,value:0}],[{type:'start',id:2},{type:'finish',id:2,value:1},{type:'start',id:3},{type:'finish',id:3,value:2}]],a=>{let requestId=null,value=null;for(const x of a){if(x.type==='start')requestId=x.id;else if(x.id===requestId)value=x.value;}return {requestId,value};},'let requestId=null,value=null;for(const e of data){if(e.type==="start")requestId=e.id;else if(e.id===requestId)value=e.value;}console.log(JSON.stringify({requestId,value}));',null,1);
js('javascript','deep-number-total',3,'JSON может содержать вложенные объекты и массивы. Сложите все числовые листья; boolean и строки игнорируются.','Произвольное JSON-значение, глубина до 15; целые числа в диапазоне ±10000.','Целое число.',[null,[],{a:[1,{b:-2}],c:true},[0,'4',3],{x:{y:[5,5]}}],function total(x){return typeof x==='number'?x:x&&typeof x==='object'?sum(Object.values(x).map(total)):0;},'(()=>{const visit=x=>typeof x==="number"?x:x&&typeof x==="object"?Object.values(x).reduce((s,v)=>s+visit(v),0):0;return visit(data);})()',null,2);
js('javascript','interval-union-duration',3,'Вычислите длину объединения полуоткрытых интервалов [start,end), start<=end. Пересечения не считаются дважды.','Массив пар целых чисел, длина до 100, границы 0..1000.','Целое число.',[[],[[0,2]],[[0,3],[2,5]],[[1,1],[1,2],[2,4]],[[4,8],[0,1],[4,8]]],a=>new Set(a.flatMap(([l,r])=>Array.from({length:r-l},(_,i)=>l+i))).size,'(()=>{let total=0,end=-Infinity;for(const[l,r]of data.slice().sort((a,b)=>a[0]-b[0])){total+=Math.max(0,r-Math.max(l,end));end=Math.max(end,r);}return total;})()',null,2);
js('javascript','shortest-unweighted-path',3,'Верните длину кратчайшего пути from до to в ориентированном графе, либо -1. from==to даёт 0.','Объект {nodes:[целое],edges:[[from,to]],from:целое,to:целое}; все вершины заданы.','Целое число.',[{nodes:[1],edges:[],from:1,to:1},{nodes:[1,2],edges:[],from:1,to:2},{nodes:[1,2,3],edges:[[1,2],[2,3]],from:1,to:3},{nodes:[1,2,3],edges:[[1,2],[1,3],[3,2]],from:1,to:2},{nodes:[1,2],edges:[[1,2],[2,1]],from:2,to:1}],x=>{let frontier=[x.from],seen=new Set(frontier),d=0;while(frontier.length){if(frontier.includes(x.to))return d;frontier=frontier.flatMap(n=>x.edges.filter(([a])=>a===n).map(([,b])=>b)).filter(n=>!seen.has(n));frontier.forEach(n=>seen.add(n));d++;}return -1;},'(()=>{const distance=new Map([[data.from,0]]),queue=[data.from];for(let i=0;i<queue.length;i++){const n=queue[i];for(const[a,b]of data.edges)if(a===n&&!distance.has(b)){distance.set(b,distance.get(n)+1);queue.push(b);}}return distance.get(data.to)??-1;})()',null,2);
js('javascript','dependency-layers',3,'Разбейте DAG на слои: в каждом слое все оставшиеся вершины без входящих рёбер, по возрастанию. При цикле верните null.','Объект {nodes:[уникальное целое],edges:[[from,to]]}; все вершины заданы.','Массив слоёв или null.',[{nodes:[],edges:[]},{nodes:[1],edges:[]},{nodes:[1,2,3],edges:[[1,3],[2,3]]},{nodes:[1,2],edges:[[1,2],[2,1]]},{nodes:[1,2,3],edges:[[1,2],[2,3]]}],x=>{let left=[...x.nodes],layers=[];while(left.length){const layer=sorted(left.filter(n=>!x.edges.some(([a,b])=>b===n&&left.includes(a))));if(!layer.length)return null;layers.push(layer);left=left.filter(n=>!layer.includes(n));}return layers;},'(()=>{let left=data.nodes.slice(),result=[];while(left.length){const layer=left.filter(n=>!data.edges.some(([a,b])=>b===n&&left.includes(a))).sort((a,b)=>a-b);if(!layer.length)return null;result.push(layer);left=left.filter(n=>!layer.includes(n));}return result;})()',null,2);
js('javascript','versioned-event-fold',3,'Применяйте событие только если его version больше текущей версии key. Начальная версия -1. Верните последние value каждого key.','Массив {key:строка,version:неотрицательное целое,value:JSON-значение}.','JSON-объект.',[[],[{key:'a',version:0,value:1}],[{key:'a',version:2,value:2},{key:'a',version:1,value:1}],[{key:'a',version:1,value:1},{key:'a',version:1,value:9}],[{key:'__proto__',version:0,value:false}]],a=>{const m=new Map();for(const x of a)if(!m.has(x.key)||x.version>m.get(x.key).version)m.set(x.key,x);return Object.fromEntries([...m].map(([k,v])=>[k,v.value]));},'(()=>{const m=new Map();for(const x of data)if(!m.has(x.key)||x.version>m.get(x.key).version)m.set(x.key,x);return Object.fromEntries([...m].map(([k,v])=>[k,v.value]));})()',null,2);
js('javascript','deep-array-shape',3,'Вычислите максимальную глубину вложенных массивов: немассив — 0, массив — 1 плюс максимальная глубина элементов (для [] — 1). Объекты считаются немассивами.','JSON-значение глубины до 15.','Целое число.',[null,[],[1,2],[[[]],3],{a:[]}],function depth(x){return Array.isArray(x)?1+Math.max(0,...x.map(depth)):0;},'(()=>{const depth=x=>Array.isArray(x)?1+Math.max(0,...x.map(depth)):0;return depth(data);})()',null,0);
js('javascript','structural-json-equality',3,'Сравните a и b структурно: порядок ключей объектов неважен, порядок массива важен; типы должны совпадать.','Объект {a:JSON-значение,b:JSON-значение}.','boolean.',[{a:{x:1,y:2},b:{y:2,x:1}},{a:[1,2],b:[2,1]},{a:null,b:{}},{a:0,b:false},{a:{x:[1,{a:2}]},b:{x:[1,{a:2}]}}],x=>JSON.stringify(stable(x.a))===JSON.stringify(stable(x.b)),'(()=>{const equal=(a,b)=>a===b||!!a&&!!b&&typeof a==="object"&&typeof b==="object"&&Array.isArray(a)===Array.isArray(b)&&Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>Object.hasOwn(b,k)&&equal(a[k],b[k]));return equal(data.a,data.b);})()',null,0);
