py('ml','root-mean-square-error',3,'Верните RMSE, округлив до 4 знаков; для пустых массивов — null.','Объект {y:[число],pred:[число]} одинаковой длины.','Число или null.',regression,x=>x.y.length?round(Math.sqrt(sum(x.y.map((v,i)=>(v-x.pred[i])**2))/x.y.length)):null,'round(math.sqrt(sum((a-b)**2 for a,b in zip(data["y"],data["pred"]))/len(data["y"])),4) if data["y"] else None',null,1);
py('ml','r2-explicit-constant-rule',3,'Верните R²=1-SSE/SST. При SST=0 верните 1 для идеального прогноза, иначе 0. Для [] — null. Округлите до 4 знаков.','Объект {y:[число],pred:[число]} одинаковой длины.','Число или null.',regression,x=>{if(!x.y.length)return null;const sse=sum(x.y.map((v,i)=>(v-x.pred[i])**2)),sst=sum(x.y.map(v=>(v-sum(x.y)/x.y.length)**2));return sst?round(1-sse/sst):sse?0:1;},'(lambda sse,sst: round(1-sse/sst,4) if sst else (0 if sse else 1))(sum((a-b)**2 for a,b in zip(data["y"],data["pred"])),sum((a-sum(data["y"])/len(data["y"]))**2 for a in data["y"])) if data["y"] else None',null,1);
py('ml','brier-score',3,'Верните mean((p-y)²), округлив до 4 знаков; для [] — null.','Объект {y:[0|1],p:[вероятность]} одинаковой длины.','Число или null.',[{y:[],p:[]},{y:[1],p:[1]},{y:[0,1],p:[0.2,0.8]},{y:[1,0],p:[0,1]},{y:[0],p:[0.5]}],x=>x.y.length?round(sum(x.y.map((v,i)=>(v-x.p[i])**2))/x.y.length):null,'round(sum((p-y)**2 for y,p in zip(data["y"],data["p"]))/len(data["y"]),4) if data["y"] else None',null,1);
py('ml','binary-logloss-clipped',3,'Верните log loss с натуральным логарифмом. Ограничьте p диапазоном [0.000001,0.999999]. Для [] — null. Округлите до 4 знаков.','Объект {y:[0|1],p:[вероятность]} одинаковой длины.','Число или null.',[{y:[],p:[]},{y:[1],p:[1]},{y:[0,1],p:[0.2,0.8]},{y:[1,0],p:[0,1]},{y:[0],p:[0.5]}],x=>x.y.length?round(-sum(x.y.map((v,i)=>{const p=Math.min(0.999999,Math.max(0.000001,x.p[i]));return v*Math.log(p)+(1-v)*Math.log(1-p);}))/x.y.length):null,'round(-sum(y*math.log(min(.999999,max(.000001,p)))+(1-y)*math.log(1-min(.999999,max(.000001,p))) for y,p in zip(data["y"],data["p"]))/len(data["y"]),4) if data["y"] else None',null,1);
py('ml','threshold-search-f1',3,'Выберите threshold из candidates с максимальным F1; при равенстве — наименьший threshold. label=1 при p>=threshold. Нулевой знаменатель F1 даёт 0.','Объект {y:[0|1],p:[вероятность],candidates:непустой массив вероятностей}; y,p равнодлинны.','Число threshold.',[{y:[],p:[],candidates:[0.2,0.7]},{y:[1],p:[0.5],candidates:[0.4,0.5,0.6]},{y:[1,0],p:[0.8,0.2],candidates:[0.2,0.5,0.9]},{y:[0,0],p:[0.2,0.7],candidates:[0,1]},{y:[1,1],p:[0.1,0.4],candidates:[0.1,0.3]}],x=>[...x.candidates].sort((a,b)=>a-b).map(t=>{const p=x.p.map(v=>Number(v>=t)),z={y:x.y,pred:p};return {t,f:sum(z.y)+sum(p)?2*tp(z)/(sum(z.y)+sum(p)):0};}).sort((a,b)=>b.f-a.f||a.t-b.t)[0].t,'min(data["candidates"],key=lambda t:(-(2*sum(y==1 and p>=t for y,p in zip(data["y"],data["p"]))/ (sum(data["y"])+sum(p>=t for p in data["p"])) if sum(data["y"])+sum(p>=t for p in data["p"]) else 0),t))',null,0);
