jp('backend','atomic-idempotent-debit',3,'Обработайте списания: первый key разрешён, если хватает balance; успешные key запоминаются. Повтор успешного key даёт 200 без списания, недостаток денег — 409 и key не запоминается.','Объект {balance:неотрицательное целое,events:[{key:строка,amount:неотрицательное целое}]}.','Объект {balance,statuses}.',transactionInputs,x=>{let balance=x.balance;const seen=new Set();return {statuses:x.events.map(e=>{if(seen.has(e.key))return 200;if(e.amount>balance)return 409;balance-=e.amount;seen.add(e.key);return 200;}),get balance(){return balance;}};},'let balance=data.balance;const seen=new Set();const statuses=data.events.map(e=>{if(seen.has(e.key))return 200;if(e.amount>balance)return 409;balance-=e.amount;seen.add(e.key);return 200;});console.log(JSON.stringify({balance,statuses}));',null,1,'typescript');
