js('backend','overlapping-reservations',3,'Для полуоткрытых броней [start,end) верните индексы броней, пересекающихся хотя бы с другой. Касание границ допустимо.','Массив пар целых чисел, start<end.','Индексы по возрастанию.',[[],[[0,1]],[[0,2],[2,3]],[[0,3],[1,2],[4,5]],[[0,2],[0,2]]],a=>a.flatMap(([l,r],i)=>a.some(([s,e],j)=>i!==j&&l<e&&s<r)?[i]:[]),'data.flatMap(([l,r],i)=>data.some(([s,e],j)=>i!==j&&l<e&&s<r)?[i]:[])',null,1,'typescript');
jp('backend','circuit-breaker-fold',3,'Breaker закрыт. После двух последовательных fail он открывается; следующие события игнорируются до reset. success в закрытом состоянии обнуляет failures, reset закрывает.','Массив строк "success","fail","reset".','Объект {open:boolean,failures:целое}.',[[],['fail'],['fail','fail','success'],['fail','success','fail'],['fail','fail','reset','success']],a=>{let open=false,failures=0;for(const e of a){if(e==='reset'){open=false;failures=0;}else if(!open){failures=e==='success'?0:failures+1;if(failures>=2)open=true;}}return {open,failures};},'let open=false,failures=0;for(const e of data){if(e==="reset"){open=false;failures=0;}else if(!open){failures=e==="success"?0:failures+1;if(failures>=2)open=true;}}console.log(JSON.stringify({open,failures}));',null,2,'typescript');
jp('backend','optimistic-patch-value',3,'Ресурс {version,value} принимает PATCH {expectedVersion,delta}. При совпадении добавьте delta, увеличьте version и верните 200, иначе 409.','Объект {version:целое,value:целое,requests:[{expectedVersion:целое,delta:целое}]}.','Объект {version,value,statuses}.',[{version:0,value:0,requests:[]},{version:1,value:4,requests:[{expectedVersion:1,delta:2}]},{version:1,value:0,requests:[{expectedVersion:0,delta:9}]},{version:0,value:2,requests:[{expectedVersion:0,delta:1},{expectedVersion:0,delta:9}]},{version:2,value:5,requests:[{expectedVersion:2,delta:-5},{expectedVersion:3,delta:0}]}],x=>{let {version,value}=x;const statuses=x.requests.map(r=>r.expectedVersion===version?(version++,value+=r.delta,200):409);return {version,value,statuses};},'let {version,value}=data;const statuses=data.requests.map(r=>r.expectedVersion===version?(version++,value+=r.delta,200):409);console.log(JSON.stringify({version,value,statuses}));',null,1,'typescript');
js('backend','outbox-publish-ack',3,'События уже сохранены в outbox. Верните id строк committed=true и acknowledged=false, сортируя по created, затем id.','Массив {id:уникальное целое,created:целое,committed:boolean,acknowledged:boolean}.','Массив id.',[[],[{id:1,created:0,committed:true,acknowledged:false}],[{id:2,created:0,committed:true,acknowledged:false},{id:1,created:0,committed:true,acknowledged:false}],[{id:3,created:2,committed:false,acknowledged:false}],[{id:1,created:1,committed:true,acknowledged:true},{id:2,created:0,committed:true,acknowledged:false}]],a=>a.filter(x=>x.committed&&!x.acknowledged).sort((a,b)=>a.created-b.created||a.id-b.id).map(x=>x.id),'data.filter(x=>x.committed&&!x.acknowledged).sort((a,b)=>a.created-b.created||a.id-b.id).map(x=>x.id)',null,1,'typescript');
js('backend','conditional-get-policy',3,'Ресурс имеет version. Если ifNoneMatch равен строке "v"+version, верните {status:304,body:null}, иначе {status:200,body:value}.','Массив {version:целое,ifNoneMatch:строка|null,value:JSON-значение}.','Массив ответов.',[[],[{version:0,ifNoneMatch:'v0',value:1}],[{version:1,ifNoneMatch:null,value:0}],[{version:1,ifNoneMatch:'v2',value:false}],[{version:2,ifNoneMatch:'v2',value:null},{version:3,ifNoneMatch:'v2',value:'x'}]],a=>a.map(x=>x.ifNoneMatch==='v'+x.version?{status:304,body:null}:{status:200,body:x.value}),'data.map(x=>x.ifNoneMatch==="v"+x.version?{status:304,body:null}:{status:200,body:x.value})',null,0,'typescript');
js('backend','cursor-total-order',3,'Верните записи после курсора (time,id): time больше, либо time равен и id больше. Сортируйте time,id по возрастанию, ограничьте limit.','Объект {rows:[{id:уникальное целое,time:целое}],cursor:{time:целое,id:целое},limit:целое>=0}.','Массив id.',API.map((rows,i)=>({rows,cursor:{time:i-1,id:1},limit:i%3})),x=>x.rows.filter(r=>r.time>x.cursor.time||r.time===x.cursor.time&&r.id>x.cursor.id).sort((a,b)=>a.time-b.time||a.id-b.id).slice(0,x.limit).map(r=>r.id),'data.rows.filter(r=>r.time>data.cursor.time||r.time===data.cursor.time&&r.id>data.cursor.id).sort((a,b)=>a.time-b.time||a.id-b.id).slice(0,data.limit).map(r=>r.id)',null,0,'typescript');
// QA coding exercises model actual oracles, contract checks and CI decisions.
const qaRows=[[],[{id:'a',expected:1,actual:1,duration:0,status:'passed',requirement:'R1',attempt:1}],[{id:'a',expected:0,actual:1,duration:10,status:'failed',requirement:'R1',attempt:1},{id:'b',expected:false,actual:false,duration:2,status:'passed',requirement:'R2',attempt:1}],[{id:'x',expected:null,actual:0,duration:20,status:'skipped',requirement:'R2',attempt:2}],[{id:'a',expected:[1,2],actual:[2,1],duration:8,status:'failed',requirement:'R1',attempt:1},{id:'a',expected:[1,2],actual:[1,2],duration:3,status:'passed',requirement:'R1',attempt:2}]];
const qaOps=[
 ['passed-identifiers',1,'Верните id успешно пройденных проверок status=passed.',a=>a.filter(x=>x.status==='passed').map(x=>x.id),'data.filter(x=>x.status==="passed").map(x=>x.id)'],
 ['failed-identifiers',1,'Верните id упавших проверок status=failed.',a=>a.filter(x=>x.status==='failed').map(x=>x.id),'data.filter(x=>x.status==="failed").map(x=>x.id)'],
 ['skipped-count',1,'Посчитайте пропущенные проверки status=skipped.',a=>a.filter(x=>x.status==='skipped').length,'data.filter(x=>x.status==="skipped").length'],
 ['duration-total',1,'Посчитайте суммарное время прогонов.',a=>sum(a.map(x=>x.duration)),'data.reduce((s,x)=>s+x.duration,0)'],
 ['strict-scalar-oracle',1,'Верните boolean сравнения expected===actual. Для объектов/массивов независимо десериализованные значения не являются одной ссылкой.',a=>a.map(x=>x.expected===x.actual),'data.map(x=>x.expected===x.actual)'],
 ['timeout-identifiers',1,'Таймаут 10 включительно допустим. Верните id прогонов с duration>10.',a=>a.filter(x=>x.duration>10).map(x=>x.id),'data.filter(x=>x.duration>10).map(x=>x.id)'],
 ['executed-requirements',1,'Верните разные requirement по первой встрече, исключая skipped.',a=>[...new Set(a.filter(x=>x.status!=='skipped').map(x=>x.requirement))],'[...new Set(data.filter(x=>x.status!=="skipped").map(x=>x.requirement))]'],
 ['ci-success-with-skips',1,'CI успешен, если нет failed. skipped не считается ошибкой, пустой набор успешен.',a=>!a.some(x=>x.status==='failed'),'!data.some(x=>x.status==="failed")'],
 ['latest-attempt-results',2,'Для каждого id оставьте прогон с максимальным attempt; при равенстве — последний во входе. Верните {id,status} по id лексикографически.',a=>[...new Set(a.map(x=>x.id))].sort().map(id=>{const row=a.filter(x=>x.id===id).sort((a,b)=>b.attempt-a.attempt).filter((x,_,z)=>x.attempt===z[0].attempt).at(-1);return {id,status:row.status};}),'[...new Set(data.map(x=>x.id))].sort().map(id=>({id,status:data.filter(x=>x.id===id).reduce((best,x)=>x.attempt>=best.attempt?x:best).status}))'],
 ['flaky-identifiers',2,'Flaky id имеет хотя бы один passed и один failed. Верните такие id по возрастанию, skipped игнорируется.',a=>[...new Set(a.map(x=>x.id))].sort().filter(id=>a.some(x=>x.id===id&&x.status==='passed')&&a.some(x=>x.id===id&&x.status==='failed')),'[...new Set(data.map(x=>x.id))].sort().filter(id=>data.some(x=>x.id===id&&x.status==="passed")&&data.some(x=>x.id===id&&x.status==="failed"))'],
 ['requirement-all-pass',2,'Требование подтверждено, если все его прогоны passed и есть хотя бы один. Верните requirement по возрастанию.',a=>[...new Set(a.map(x=>x.requirement))].sort().filter(r=>a.filter(x=>x.requirement===r).every(x=>x.status==='passed')),'[...new Set(data.map(x=>x.requirement))].sort().filter(r=>data.filter(x=>x.requirement===r).every(x=>x.status==="passed"))'],
 ['shard-by-duration',2,'Назначьте проверки двум шардам: каждый следующий прогон идёт в шард с меньшей текущей суммой duration, при равенстве — 0. Верните индексы шардов.',a=>{const loads=[0,0];return a.map(x=>{const i=loads[0]<=loads[1]?0:1;loads[i]+=x.duration;return i;});},'(()=>{const loads=[0,0];return data.map(x=>{const i=loads[0]<=loads[1]?0:1;loads[i]+=x.duration;return i;});})()'],
 ['unique-fixture-names',2,'Имя фикстуры — id+":"+attempt. Верните индексы повторов имени.',a=>a.flatMap((x,i)=>a.slice(0,i).some(y=>y.id===x.id&&y.attempt===x.attempt)?[i]:[]),'data.flatMap((x,i)=>data.slice(0,i).some(y=>y.id===x.id&&y.attempt===x.attempt)?[i]:[])'],
 ['result-frequency-table',2,'Верните количество прогонов каждого status, включая только встретившиеся статусы.',a=>Object.fromEntries([...new Set(a.map(x=>x.status))].map(s=>[s,a.filter(x=>x.status===s).length])),'Object.fromEntries([...new Set(data.map(x=>x.status))].map(s=>[s,data.filter(x=>x.status===s).length]))'],
 ['quarantine-after-two-failures',2,'Верните id, у которых минимум два failed, без дублей и по возрастанию.',a=>[...new Set(a.map(x=>x.id))].sort().filter(id=>a.filter(x=>x.id===id&&x.status==='failed').length>=2),'[...new Set(data.map(x=>x.id))].sort().filter(id=>data.filter(x=>x.id===id&&x.status==="failed").length>=2)'],
 ['ci-budget-selection',2,'Бюджет 10. Последовательно включайте прогон, только если его duration помещается в остаток; не помещающийся пропускайте и продолжайте. Верните id.',a=>{let n=10;return a.flatMap(x=>x.duration<=n?(n-=x.duration,[x.id]):[]);},'(()=>{let n=10;return data.flatMap(x=>x.duration<=n?(n-=x.duration,[x.id]):[]);})()'],
 ['deep-response-contract',3,'Сравните expected и actual структурно; порядок ключей объекта неважен, порядок массивов важен.',a=>a.map(x=>JSON.stringify(stable(x.expected))===JSON.stringify(stable(x.actual))),'(()=>{const eq=(a,b)=>a===b||!!a&&!!b&&typeof a==="object"&&typeof b==="object"&&Array.isArray(a)===Array.isArray(b)&&Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>Object.hasOwn(b,k)&&eq(a[k],b[k]));return data.map(x=>eq(x.expected,x.actual));})()'],
 ['retry-recovered-identifiers',3,'Верните id, где был failed, затем passed с большим attempt. skipped не влияет. Результат лексикографический.',a=>[...new Set(a.map(x=>x.id))].sort().filter(id=>a.some(x=>x.id===id&&x.status==='failed'&&a.some(y=>y.id===id&&y.status==='passed'&&y.attempt>x.attempt))),'[...new Set(data.map(x=>x.id))].sort().filter(id=>data.some(x=>x.id===id&&x.status==="failed"&&data.some(y=>y.id===id&&y.status==="passed"&&y.attempt>x.attempt)))'],
 ['test-case-priority',3,'Отсортируйте прогоны: failed, skipped, passed; внутри статуса duration по убыванию, затем id. Верните id.',a=>[...a].sort((a,b)=>['failed','skipped','passed'].indexOf(a.status)-['failed','skipped','passed'].indexOf(b.status)||b.duration-a.duration||(a.id<b.id?-1:a.id>b.id?1:0)).map(x=>x.id),'data.slice().sort((a,b)=>["failed","skipped","passed"].indexOf(a.status)-["failed","skipped","passed"].indexOf(b.status)||b.duration-a.duration||(a.id<b.id?-1:a.id>b.id?1:0)).map(x=>x.id)'],
 ['regression-from-success',3,'Верните id с passed на меньшем attempt и failed на большем attempt, по возрастанию.',a=>[...new Set(a.map(x=>x.id))].sort().filter(id=>a.some(x=>x.id===id&&x.status==='passed'&&a.some(y=>y.id===id&&y.status==='failed'&&y.attempt>x.attempt))),'[...new Set(data.map(x=>x.id))].sort().filter(id=>data.some(x=>x.id===id&&x.status==="passed"&&data.some(y=>y.id===id&&y.status==="failed"&&y.attempt>x.attempt)))'],
 ['minimum-retry-count',3,'Для каждого id верните число дополнительных попыток: max(attempt)-1. Пары [id,count] сортируются по id.',a=>[...new Set(a.map(x=>x.id))].sort().map(id=>[id,Math.max(...a.filter(x=>x.id===id).map(x=>x.attempt))-1]),'[...new Set(data.map(x=>x.id))].sort().map(id=>[id,Math.max(...data.filter(x=>x.id===id).map(x=>x.attempt))-1])'],
 ['latest-ci-verdict',3,'CI оценивает только последний attempt каждого id (при равенстве — последний во входе). Верните passed, если все последние статусы passed, иначе failed. Пустой набор passed.',a=>[...new Set(a.map(x=>x.id))].every(id=>a.filter(x=>x.id===id).reduce((z,x)=>x.attempt>=z.attempt?x:z).status==='passed')?'passed':'failed','[...new Set(data.map(x=>x.id))].every(id=>data.filter(x=>x.id===id).reduce((z,x)=>x.attempt>=z.attempt?x:z).status==="passed")?"passed":"failed"'],
 ['required-response-fields',3,'Верните индексы actual, которые не являются объектом с собственным id целого типа и status строкового типа. Массивы недопустимы.',a=>a.flatMap((x,i)=>x.actual&&typeof x.actual==='object'&&!Array.isArray(x.actual)&&Object.hasOwn(x.actual,'id')&&Number.isInteger(x.actual.id)&&typeof x.actual.status==='string'?[]:[i]),'data.flatMap((x,i)=>x.actual&&typeof x.actual==="object"&&!Array.isArray(x.actual)&&Object.hasOwn(x.actual,"id")&&Number.isInteger(x.actual.id)&&typeof x.actual.status==="string"?[]:[i])'],
 ['coverage-with-successful-retry',3,'Требование покрыто, если у каждого его id последний attempt passed. Верните requirement по возрастанию.',a=>[...new Set(a.map(x=>x.requirement))].sort().filter(r=>[...new Set(a.filter(x=>x.requirement===r).map(x=>x.id))].every(id=>a.filter(x=>x.id===id&&x.requirement===r).reduce((z,x)=>x.attempt>=z.attempt?x:z).status==='passed')),'[...new Set(data.map(x=>x.requirement))].sort().filter(r=>[...new Set(data.filter(x=>x.requirement===r).map(x=>x.id))].every(id=>data.filter(x=>x.id===id&&x.requirement===r).reduce((z,x)=>x.attempt>=z.attempt?x:z).status==="passed"))'],
];
for(const[id,d,p,o,e]of qaOps)js('automation',id,d,p+' Сохраняйте входной порядок, если не указана сортировка.','Массив {id:строка,expected:JSON-значение,actual:JSON-значение,duration:неотрицательное целое,status:"passed"|"failed"|"skipped",requirement:строка,attempt:положительное целое}.','JSON-результат согласно условию.',qaRows,o,e,null,d===1?0:d===2?1:2);
const SQL_DATA=[[],[{id:1,category:'a',value:0,active:1,created:0}],[{id:1,category:'a',value:3,active:1,created:1},{id:2,category:'a',value:7,active:0,created:2},{id:3,category:'b',value:null,active:1,created:2}],[{id:4,category:'b',value:-2,active:0,created:0},{id:1,category:'a',value:5,active:1,created:1},{id:2,category:'b',value:5,active:1,created:1}],[{id:5,category:'a',value:null,active:0,created:3},{id:2,category:'a',value:5,active:1,created:1},{id:1,category:'a',value:5,active:1,created:1}]];
const sqlLiteral=x=>x===null?'NULL':typeof x==='string'?"'"+x.replaceAll("'","''")+"'":String(x);
const sqlFixture=rows=>'CREATE TABLE records(id integer PRIMARY KEY, category text NOT NULL, value integer, active integer NOT NULL, created integer NOT NULL);\n'+(rows.length?'INSERT INTO records VALUES '+rows.map(x=>'('+[x.id,x.category,x.value,x.active,x.created].map(sqlLiteral).join(',')+')').join(',')+';':'');
const textRows=rows=>rows.map(r=>(Array.isArray(r)?r:[r]).map(v=>v??'').join('|')).join('\n');
const byId=a=>[...a].sort((a,b)=>a.id-b.id);
const cats=a=>[...new Set(a.map(x=>x.category))].sort();
const sqlTasks=[
 ['active-filter',1,'Выведите id активных записей active=1 по возрастанию id.','SELECT id FROM records WHERE active=1 ORDER BY id;',a=>byId(a.filter(x=>x.active===1)).map(x=>x.id),0],
 ['nullable-values',1,'Выведите id записей с value IS NULL по возрастанию id.','SELECT id FROM records WHERE value IS NULL ORDER BY id;',a=>byId(a.filter(x=>x.value===null)).map(x=>x.id),0],
 ['total-row-count',1,'Выведите общее число строк, включая NULL в value.','SELECT COUNT(*) FROM records;',a=>[a.length],0],
 ['nonnull-count',1,'Выведите число ненулевых (не NULL) значений value. Число 0 учитывается.','SELECT COUNT(value) FROM records;',a=>[a.filter(x=>x.value!==null).length],0],
 ['positive-values',1,'Выведите id и value только для value>0, по id.','SELECT id,value FROM records WHERE value>0 ORDER BY id;',a=>byId(a.filter(x=>x.value>0)).map(x=>[x.id,x.value]),0],
 ['distinct-categories',1,'Выведите разные category по алфавиту.','SELECT DISTINCT category FROM records ORDER BY category;',a=>cats(a),0],
 ['coalesce-value',1,'Выведите id и value, заменив NULL на -1, по id.','SELECT id,COALESCE(value,-1) FROM records ORDER BY id;',a=>byId(a).map(x=>[x.id,x.value??-1]),0],
 ['top-two-created',1,'Выведите id двух последних записей по created DESC,id ASC.','SELECT id FROM records ORDER BY created DESC,id ASC LIMIT 2;',a=>[...a].sort((a,b)=>b.created-a.created||a.id-b.id).slice(0,2).map(x=>x.id),0],
 ['group-row-count',2,'Выведите category и количество строк каждой категории по category.','SELECT category,COUNT(*) FROM records GROUP BY category ORDER BY category;',a=>cats(a).map(c=>[c,a.filter(x=>x.category===c).length]),1],
 ['group-sum-null-zero',2,'Выведите category и сумму value; если все value в группе NULL, сумма 0. Порядок category.','SELECT category,COALESCE(SUM(value),0) FROM records GROUP BY category ORDER BY category;',a=>cats(a).map(c=>[c,sum(a.filter(x=>x.category===c).map(x=>x.value??0))]),1],
 ['having-multiple-rows',2,'Выведите category групп минимум с двумя строками, по category.','SELECT category FROM records GROUP BY category HAVING COUNT(*)>=2 ORDER BY category;',a=>cats(a).filter(c=>a.filter(x=>x.category===c).length>=2),1],
 ['conditional-counts',2,'Выведите category и число active=1 в каждой группе. Порядок category.','SELECT category,COUNT(*) FILTER(WHERE active=1) FROM records GROUP BY category ORDER BY category;',a=>cats(a).map(c=>[c,a.filter(x=>x.category===c&&x.active===1).length]),1],
 ['self-join-pairs',2,'Выведите пары id одной category с left.id<right.id. Порядок left.id,right.id.','SELECT a.id,b.id FROM records a JOIN records b ON a.category=b.category AND a.id<b.id ORDER BY a.id,b.id;',a=>byId(a).flatMap(x=>byId(a).filter(y=>y.category===x.category&&y.id>x.id).map(y=>[x.id,y.id])),1],
 ['correlated-higher-value',2,'Выведите id строк, для которых существует другая строка той же category с большим value. NULL не сравнивается. Порядок id.','SELECT a.id FROM records a WHERE EXISTS(SELECT 1 FROM records b WHERE b.category=a.category AND b.value>a.value) ORDER BY a.id;',a=>byId(a).filter(x=>x.value!==null&&a.some(y=>y.category===x.category&&y.value!==null&&y.value>x.value)).map(x=>x.id),1],
 ['category-max-value',2,'Выведите category и максимальное value. Группа с одними NULL даёт пустое поле. Порядок category.','SELECT category,MAX(value) FROM records GROUP BY category ORDER BY category;',a=>cats(a).map(c=>{const v=a.filter(x=>x.category===c&&x.value!==null).map(x=>x.value);return [c,v.length?Math.max(...v):null];}),1],
 ['active-category-completeness',2,'Выведите category, в которых все строки active=1. Порядок category.','SELECT category FROM records GROUP BY category HAVING MIN(active)=1 ORDER BY category;',a=>cats(a).filter(c=>a.filter(x=>x.category===c).every(x=>x.active===1)),1],
 ['running-value-by-category',3,'Выведите id и накопительную сумму value внутри category в порядке created,id. NULL считается 0. Итог сортируется по id. Явно используйте ROWS.','SELECT id,SUM(COALESCE(value,0)) OVER(PARTITION BY category ORDER BY created,id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) FROM records ORDER BY id;',a=>byId(a).map(x=>[x.id,sum(a.filter(y=>y.category===x.category&&(y.created<x.created||y.created===x.created&&y.id<=x.id)).map(y=>y.value??0))]),1],
 ['dense-rank-score',3,'Выведите id и DENSE_RANK по value DESC NULLS LAST внутри category, затем по id.','SELECT id,DENSE_RANK() OVER(PARTITION BY category ORDER BY value DESC NULLS LAST) FROM records ORDER BY id;',a=>byId(a).map(x=>{const values=[...new Set(a.filter(y=>y.category===x.category).map(y=>y.value))].sort((a,b)=>a===null?1:b===null?-1:b-a);return [x.id,values.indexOf(x.value)+1];}),1],
 ['first-per-category',3,'Выведите id самой ранней записи каждой category, при равенстве created — меньший id. Итог по category.','SELECT id FROM (SELECT id,category,ROW_NUMBER() OVER(PARTITION BY category ORDER BY created,id) AS n FROM records) t WHERE n=1 ORDER BY category;',a=>cats(a).map(c=>[...a].filter(x=>x.category===c).sort((a,b)=>a.created-b.created||a.id-b.id)[0].id),1],
 ['lag-created-delta',3,'Выведите id и разность created с предыдущей записью category в порядке created,id. Для первой — NULL (пустое поле). Итог по id.','SELECT id,created-LAG(created) OVER(PARTITION BY category ORDER BY created,id) FROM records ORDER BY id;',a=>byId(a).map(x=>{const group=a.filter(y=>y.category===x.category).sort((a,b)=>a.created-b.created||a.id-b.id),i=group.findIndex(y=>y.id===x.id);return [x.id,i?x.created-group[i-1].created:null];}),1],
 ['above-group-mean',3,'Выведите id, где value строго больше среднего не-NULL value своей category. Итог по id.','SELECT a.id FROM records a WHERE a.value>(SELECT AVG(b.value) FROM records b WHERE b.category=a.category) ORDER BY a.id;',a=>byId(a).filter(x=>{const v=a.filter(y=>y.category===x.category&&y.value!==null).map(y=>y.value);return x.value!==null&&x.value>sum(v)/v.length;}).map(x=>x.id),1],
 ['group-count-without-current',3,'Выведите id и число других строк той же category. Итог по id.','SELECT id,COUNT(*) OVER(PARTITION BY category)-1 FROM records ORDER BY id;',a=>byId(a).map(x=>[x.id,a.filter(y=>y.category===x.category).length-1]),1],
 ['consecutive-id-islands',3,'Выведите начало и конец каждого непрерывного диапазона существующих id. Итог по началу диапазона.','WITH numbered AS (SELECT id,id-ROW_NUMBER() OVER(ORDER BY id) AS grp FROM records) SELECT MIN(id),MAX(id) FROM numbered GROUP BY grp ORDER BY MIN(id);',a=>{const ids=byId(a).map(x=>x.id),out=[];for(const id of ids){if(!out.length||id!==out.at(-1)[1]+1)out.push([id,id]);else out.at(-1)[1]=id;}return out;},1],
 ['latest-active-version-per-category',3,'Для каждой category выберите самую позднюю активную запись по created DESC,id DESC. Группы без активных строк отсутствуют. Итог по category.','SELECT id FROM (SELECT id,category,ROW_NUMBER() OVER(PARTITION BY category ORDER BY created DESC,id DESC) AS n FROM records WHERE active=1) t WHERE n=1 ORDER BY category;',a=>cats(a.filter(x=>x.active===1)).map(c=>a.filter(x=>x.category===c&&x.active===1).sort((a,b)=>b.created-a.created||b.id-a.id)[0].id),1],
];
for(const[id,d,p,source,oracle,c]of sqlTasks)add('sql',id,d,p,'PostgreSQL 15. Таблица records(id integer PRIMARY KEY,category text NOT NULL,value integer NULL,active integer 0|1,created integer). Данные создаются SQL-командами из stdin.','Результат SELECT: строки разделены переводом строки, столбцы — |, NULL — пустое поле; без заголовка.',SQL_DATA.map(sqlFixture),s=>textRows(oracle(SQL_DATA[SQL_DATA.map(sqlFixture).indexOf(s)])),source,'sql',null,c);
// Linux / operations: log processing, health checks, releases and resource budgets.
const LOGS=['','api 200 5\n','api 200 5\nweb 503 20\napi 500 10\n','db 404 0\napi 200 3\n','web 500 8\nweb 503 12\napi 429 4\n'];
const parseLog=s=>s.trim()?s.trim().split('\n').map(l=>{const[service,status,latency]=l.split(' ');return {service,status:+status,latency:+latency};}):[];
const bashOps=[
 ['service-column',1,'Выведите имя сервиса из каждой строки в исходном порядке.',s=>parseLog(s).map(x=>x.service).join('\n'),"awk '{print $1}'"],
 ['healthy-service-lines',1,'Выведите сервисы строк с HTTP-статусом 200..299 в исходном порядке.',s=>parseLog(s).filter(x=>x.status>=200&&x.status<300).map(x=>x.service).join('\n'),"awk '$2>=200 && $2<300 {print $1}'"],
 ['non-success-count',1,'Посчитайте строки со статусом вне 200..299.',s=>String(parseLog(s).filter(x=>x.status<200||x.status>=300).length),"awk '$2<200 || $2>=300 {n++} END {print n+0}'"],
 ['latency-total',1,'Выведите сумму latency; для пустого ввода — 0.',s=>String(sum(parseLog(s).map(x=>x.latency))),"awk '{n+=$3} END {print n+0}'"],
 ['slow-services',1,'Выведите сервисы строк с latency>10, в порядке входа.',s=>parseLog(s).filter(x=>x.latency>10).map(x=>x.service).join('\n'),"awk '$3>10 {print $1}'"],
 ['request-row-number',1,'Пронумеруйте строки с 1: выведите номер и сервис через пробел.',s=>parseLog(s).map((x,i)=>(i+1)+' '+x.service).join('\n'),"awk '{print NR,$1}'"],
 ['status-column',1,'Выведите HTTP-статус каждой строки.',s=>parseLog(s).map(x=>x.status).join('\n'),"awk '{print $2}'"],
 ['latency-maximum',1,'Выведите максимальное latency; для пустого ввода — 0.',s=>String(Math.max(0,...parseLog(s).map(x=>x.latency))),"awk '$3>m {m=$3} END {print m+0}'"],
 ['service-request-counts',2,'Выведите сервис и число его запросов через пробел, сервисы по алфавиту.',s=>{const a=parseLog(s);return [...new Set(a.map(x=>x.service))].sort().map(k=>k+' '+a.filter(x=>x.service===k).length).join('\n');},"awk '{n[$1]++} END {for(k in n) print k,n[k]}' | LC_ALL=C sort"],
 ['service-latency-maxima',2,'Выведите сервис и его максимальное latency, сервисы по алфавиту.',s=>{const a=parseLog(s);return [...new Set(a.map(x=>x.service))].sort().map(k=>k+' '+Math.max(...a.filter(x=>x.service===k).map(x=>x.latency))).join('\n');},"awk '!($1 in m)||$3>m[$1] {m[$1]=$3} END {for(k in m) print k,m[k]}' | LC_ALL=C sort"],
 ['distinct-statuses',2,'Выведите разные HTTP-статусы по числовому возрастанию.',s=>sorted([...new Set(parseLog(s).map(x=>x.status))]).join('\n'),"awk '{print $2}' | LC_ALL=C sort -nu"],
 ['status-histogram',2,'Выведите статус и число запросов через пробел, по статусу.',s=>{const a=parseLog(s);return sorted([...new Set(a.map(x=>x.status))]).map(k=>k+' '+a.filter(x=>x.status===k).length).join('\n');},"awk '{n[$2]++} END {for(k in n) print k,n[k]}' | LC_ALL=C sort -n"],
 ['service-all-healthy',2,'Выведите сервисы, у которых все запросы 2xx, по алфавиту.',s=>{const a=parseLog(s);return [...new Set(a.map(x=>x.service))].sort().filter(k=>a.filter(x=>x.service===k).every(x=>x.status>=200&&x.status<300)).join('\n');},"awk '{seen[$1]=1;if($2<200||$2>=300)bad[$1]=1} END {for(k in seen)if(!bad[k])print k}' | LC_ALL=C sort"],
 ['distinct-service-status-pairs',2,'Выведите разные пары сервис статус по имени сервиса, затем статусу.',s=>[...new Set(parseLog(s).map(x=>x.service+' '+x.status))].sort().join('\n'),"awk '{print $1,$2}' | LC_ALL=C sort -u"],
 ['first-service-occurrence',2,'Выведите каждый сервис только при первом появлении, сохраняя порядок.',s=>[...new Set(parseLog(s).map(x=>x.service))].join('\n'),"awk '!seen[$1]++ {print $1}'"],
 ['last-service-status',2,'Выведите сервис и последний наблюдаемый статус, сервисы по алфавиту.',s=>{const a=parseLog(s);return [...new Set(a.map(x=>x.service))].sort().map(k=>k+' '+a.filter(x=>x.service===k).at(-1).status).join('\n');},"awk '{status[$1]=$2} END {for(k in status)print k,status[k]}' | LC_ALL=C sort"],
 ['service-error-basis-points',3,'Выведите сервис и долю 5xx в базисных пунктах (10000=100%), округляя вниз. Сервисы по алфавиту.',s=>{const a=parseLog(s);return [...new Set(a.map(x=>x.service))].sort().map(k=>{const r=a.filter(x=>x.service===k);return k+' '+Math.floor(10000*r.filter(x=>x.status>=500&&x.status<=599).length/r.length);}).join('\n');},"awk '{n[$1]++;if($2>=500&&$2<=599)e[$1]++} END {for(k in n)print k,int(10000*e[k]/n[k])}' | LC_ALL=C sort"],
 ['service-mean-latency-floor',3,'Выведите сервис и floor среднего latency, сервисы по алфавиту.',s=>{const a=parseLog(s);return [...new Set(a.map(x=>x.service))].sort().map(k=>{const r=a.filter(x=>x.service===k);return k+' '+Math.floor(sum(r.map(x=>x.latency))/r.length);}).join('\n');},"awk '{n[$1]++;s[$1]+=$3} END {for(k in n)print k,int(s[k]/n[k])}' | LC_ALL=C sort"],
 ['service-error-latency-total',3,'Для каждого сервиса выведите сумму latency только 5xx; сервисы без 5xx включите с 0. Порядок имени.',s=>{const a=parseLog(s);return [...new Set(a.map(x=>x.service))].sort().map(k=>k+' '+sum(a.filter(x=>x.service===k&&x.status>=500&&x.status<=599).map(x=>x.latency))).join('\n');},"awk '{seen[$1]=1;if($2>=500&&$2<=599)s[$1]+=$3} END {for(k in seen)print k,s[k]+0}' | LC_ALL=C sort"],
 ['consecutive-failure-peak',3,'Верните длину максимальной серии последовательных строк с 5xx. Любой другой статус прерывает серию.',s=>{let n=0,m=0;for(const x of parseLog(s)){n=x.status>=500&&x.status<=599?n+1:0;m=Math.max(m,n);}return String(m);},"awk '{if($2>=500&&$2<=599)n++;else n=0;if(n>m)m=n} END {print m+0}'"],
 ['unique-failed-service-count',3,'Верните число разных сервисов, у которых хотя бы один 5xx.',s=>String(new Set(parseLog(s).filter(x=>x.status>=500&&x.status<=599).map(x=>x.service)).size),"awk '$2>=500&&$2<=599 {e[$1]=1} END {for(k in e)n++;print n+0}'"],
 ['latency-nearest-rank-p95',3,'Верните p95 latency по nearest-rank: отсортируйте, возьмите элемент ceil(0.95*N), нумерация с 1. Для пустого ввода — 0.',s=>{const a=sorted(parseLog(s).map(x=>x.latency));return String(a.length?a[Math.ceil(.95*a.length)-1]:0);},"awk '{print $3}' | sort -n | awk '{a[NR]=$1} END {if(NR)print a[int(.95*NR)+(.95*NR>int(.95*NR))];else print 0}'"],
 ['most-requested-service',3,'Выведите сервис с максимальным числом запросов; при равенстве — первый по алфавиту. Для пустого ввода ничего.',s=>{const a=parseLog(s);return [...new Set(a.map(x=>x.service))].sort().sort((x,y)=>a.filter(r=>r.service===y).length-a.filter(r=>r.service===x).length)[0]??'';},"awk '{n[$1]++} END {for(k in n)print n[k],k}' | LC_ALL=C sort -k1,1nr -k2,2 | head -n1 | awk '{print $2}'"],
 ['latency-running-total',3,'Выведите накопительную сумму latency после каждой строки.',s=>parseLog(s).map((_,i)=>sum(parseLog(s).slice(0,i+1).map(x=>x.latency))).join('\n'),"awk '{s+=$3;print s}'"],
];
for(const[id,d,p,oracle,source]of bashOps)add('infrastructure',id,d,p,'Текст из stdin: каждая непустая строка service status latency, разделитель один пробел. service — ASCII-буквы; status 100..599; latency неотрицательное целое.','Текст из условия, без заголовка и пояснений.',LOGS,oracle,source,'bash',null,d===1?0:d===2?1:2);
const ranges=[{min:0,max:0,values:[]},{min:1,max:3,values:[0,1,2,3,4]},{min:-2,max:2,values:[-3,-2,0,2,3]},{min:4,max:4,values:[3,4,5]},{min:0,max:10,values:[0,0,10,11]}];
const designOps=[
 ['inclusive-range-oracle',1,'Классифицируйте каждое value: valid при min<=value<=max, иначе invalid.',x=>x.values.map(v=>v>=x.min&&v<=x.max?'valid':'invalid'),'["valid" if data["min"]<=v<=data["max"] else "invalid" for v in data["values"]]'],
 ['outside-boundaries',1,'Верните две внешние границы [min-1,max+1].',x=>[x.min-1,x.max+1],'[data["min"]-1,data["max"]+1]'],
 ['inside-boundaries',1,'Верните уникальные внутренние границы min и max, по возрастанию.',x=>sorted([...new Set([x.min,x.max])]),'sorted({data["min"],data["max"]})'],
 ['invalid-value-indices',1,'Верните индексы недопустимых значений по возрастанию.',x=>x.values.flatMap((v,i)=>v<x.min||v>x.max?[i]:[]),'[i for i,v in enumerate(data["values"]) if not data["min"]<=v<=data["max"]]'],
 ['valid-partition-size',1,'Посчитайте значения внутри допустимого диапазона, включая повторы.',x=>x.values.filter(v=>v>=x.min&&v<=x.max).length,'sum(data["min"]<=v<=data["max"] for v in data["values"])'],
 ['lower-partition',1,'Верните значения ниже min в исходном порядке.',x=>x.values.filter(v=>v<x.min),'[v for v in data["values"] if v<data["min"]]'],
 ['upper-partition',1,'Верните значения выше max в исходном порядке.',x=>x.values.filter(v=>v>x.max),'[v for v in data["values"] if v>data["max"]]'],
 ['three-partition-counts',1,'Верните {below,valid,above} — размеры классов эквивалентности.',x=>({below:x.values.filter(v=>v<x.min).length,valid:x.values.filter(v=>v>=x.min&&v<=x.max).length,above:x.values.filter(v=>v>x.max).length}),'{"below":sum(v<data["min"] for v in data["values"]),"valid":sum(data["min"]<=v<=data["max"] for v in data["values"]),"above":sum(v>data["max"] for v in data["values"])}'],
 ['boundary-coverage-missing',2,'Проверьте обязательные границы min-1,min,max,max+1. Верните ещё не проверенные значения без повторов, по возрастанию.',x=>sorted([...new Set([x.min-1,x.min,x.max,x.max+1])]).filter(v=>!x.values.includes(v)),'sorted({data["min"]-1,data["min"],data["max"],data["max"]+1}-set(data["values"]))'],
 ['distance-to-valid-class',2,'Для каждого value верните минимальное расстояние до допустимого диапазона; внутри — 0.',x=>x.values.map(v=>Math.max(x.min-v,v-x.max,0)),'[max(data["min"]-v,v-data["max"],0) for v in data["values"]]'],
 ['distinct-class-coverage',2,'Верните число представленных классов: below,valid,above. Максимум 3.',x=>new Set(x.values.map(v=>v<x.min?'below':v>x.max?'above':'valid')).size,'len({"below" if v<data["min"] else "above" if v>data["max"] else "valid" for v in data["values"]})'],
 ['minimal-representatives',2,'Для каждого представленного класса возьмите первый value. Верните объект с ключами below,valid,above только для представленных классов.',x=>{const m=new Map();for(const v of x.values){const k=v<x.min?'below':v>x.max?'above':'valid';if(!m.has(k))m.set(k,v);}return Object.fromEntries(m);},'(lambda pairs: {k:next(v for c,v in pairs if c==k) for k in dict.fromkeys(c for c,v in pairs)})([("below" if v<data["min"] else "above" if v>data["max"] else "valid",v) for v in data["values"]])'],
 ['off-by-one-low-mutations',2,'Правильный предикат min<=value<=max. Мутант min<value<=max. Верните индексы значений, различающих эти предикаты.',x=>x.values.flatMap((v,i)=>v===x.min?[i]:[]),'[i for i,v in enumerate(data["values"]) if v==data["min"]]'],
 ['off-by-one-high-mutations',2,'Мутант принимает min<=value<max вместо min<=value<=max. Верните индексы значений, убивающих мутанта.',x=>x.values.flatMap((v,i)=>v===x.max?[i]:[]),'[i for i,v in enumerate(data["values"]) if v==data["max"]]'],
 ['metamorphic-clamp-idempotence',2,'Метаморфное свойство: clamp(clamp(value))=clamp(value). Верните clamp(value) для каждого, где clamp ограничивает [min,max].',x=>x.values.map(v=>Math.min(x.max,Math.max(x.min,v))),'[min(data["max"],max(data["min"],v)) for v in data["values"]]'],
 ['duplicate-test-reduction',2,'Оставьте первый тест каждого value, сохраняя порядок. Повторное значение не расширяет покрытие этого оракула.',x=>[...new Set(x.values)],'list(dict.fromkeys(data["values"]))'],
];
for(const[id,d,p,o,e]of designOps)py('test-design',id,d,p,'Объект {min:целое,max:целое,values:[целое]}, min<=max.','JSON-результат согласно условию.',ranges,o,e,null,d===1?0:1);
const decisions=[[],[{active:true,admin:false,paid:false}],[{active:true,admin:true,paid:false},{active:false,admin:true,paid:true}],[{active:true,admin:false,paid:true},{active:false,admin:false,paid:false}],[{active:true,admin:true,paid:true},{active:true,admin:false,paid:false}]];
py('test-design','decision-oracle-xor',3,'Доступ разрешён, если active=true и ровно один из admin/paid равен true. Верните ожидаемые решения.','Массив {active:boolean,admin:boolean,paid:boolean}.','Массив boolean.',decisions,a=>a.map(x=>x.active&&x.admin!==x.paid),'[x["active"] and x["admin"]!=x["paid"] for x in data]',null,0);
py('test-design','decision-table-missing',3,'Для трёх boolean факторов active,admin,paid верните отсутствующие комбинации. Порядок false перед true, сравнение лексикографическое.','Массив {active:boolean,admin:boolean,paid:boolean}.','Массив троек [active,admin,paid].',decisions,a=>[false,true].flatMap(x=>[false,true].flatMap(y=>[false,true].flatMap(z=>a.some(r=>r.active===x&&r.admin===y&&r.paid===z)?[]:[[x,y,z]]))),'[list(c) for c in itertools.product((False,True),repeat=3) if not any((x["active"],x["admin"],x["paid"])==c for x in data)]',null,0);
py('test-design','pairwise-missing-combinations',3,'Для каждой пары факторов (0=active,1=admin,2=paid) верните отсутствующие комбинации [i,value_i,j,value_j], сортируя i,j, затем значения false,true.','Массив {active:boolean,admin:boolean,paid:boolean}.','Массив четвёрок.',decisions,a=>[0,1,2].flatMap(i=>[0,1,2].filter(j=>j>i).flatMap(j=>[false,true].flatMap(x=>[false,true].flatMap(y=>a.some(r=>Object.values(r)[i]===x&&Object.values(r)[j]===y)?[]:[[i,x,j,y]])))),'[[i,x,j,y] for i in range(3) for j in range(i+1,3) for x in (False,True) for y in (False,True) if not any((r[("active","admin","paid")[i]],r[("active","admin","paid")[j]])==(x,y) for r in data)]',null,0);
py('test-design','mutation-or-vs-and',3,'Правильный доступ: active AND (admin OR paid). Мутант: active OR (admin OR paid). Верните индексы строк, где решения различаются.','Массив {active:boolean,admin:boolean,paid:boolean}.','Массив индексов.',decisions,a=>a.flatMap((r,i)=>(r.active&&(r.admin||r.paid))!==(r.active||r.admin||r.paid)?[i]:[]),'[i for i,r in enumerate(data) if (r["active"] and (r["admin"] or r["paid"]))!=(r["active"] or r["admin"] or r["paid"])]',null,1);
const risks=[[],[{id:'a',probability:1,impact:1,cost:1}],[{id:'b',probability:3,impact:2,cost:2},{id:'a',probability:2,impact:3,cost:1}],[{id:'x',probability:0,impact:5,cost:2}],[{id:'a',probability:2,impact:2,cost:3},{id:'b',probability:1,impact:5,cost:1}]];
py('test-design','risk-weighted-order',3,'Приоритет равен probability*impact. Верните id по убыванию приоритета, при равенстве — по id.', 'Массив {id:уникальная ASCII-строка,probability:неотрицательное число,impact:неотрицательное число,cost:положительное число}.','Массив id.',risks,a=>[...a].sort((a,b)=>b.probability*b.impact-a.probability*a.impact||(a.id<b.id?-1:a.id>b.id?1:0)).map(x=>x.id),'[r["id"] for r in sorted(data,key=lambda r:(-r["probability"]*r["impact"],r["id"]))]',null,2);
py('test-design','risk-budget-maximization',3,'Бюджет тестирования равен 3. Выберите подмножество с максимальной суммой probability*impact при sum(cost)<=3. При равенстве выберите лексикографически наименьший отсортированный список id.','Массив не более 12 {id:уникальная ASCII-строка,probability:неотрицательное целое,impact:неотрицательное целое,cost:целое>=1}.','Массив id по возрастанию.',risks,a=>{let best=[],score=0;for(let mask=0;mask<2**a.length;mask++){const r=a.filter((_,i)=>mask&(1<<i));if(sum(r.map(x=>x.cost))>3)continue;const s=sum(r.map(x=>x.probability*x.impact)),ids=r.map(x=>x.id).sort();if(s>score||s===score&&JSON.stringify(ids)<JSON.stringify(best)){best=ids;score=s;}}return best;},'min((sorted(r["id"] for r in data if mask&(1<<i)) for mask in range(1<<len(data)) for i in []),default=[])',null,2);
