definitions['test-design'].at(-1).source='import json,sys,itertools\ndata=json.load(sys.stdin)\nchoices=[list(c) for n in range(len(data)+1) for c in itertools.combinations(data,n) if sum(x["cost"] for x in c)<=3]\nbest=min(choices,key=lambda c:(-sum(x["probability"]*x["impact"] for x in c),sorted(x["id"] for x in c)))\nprint(json.dumps(sorted(x["id"] for x in best)))';
py('test-design','boundary-mutant-kill-vector',3,'Есть четыре мутанта: v>min вместо v>=min; v<max вместо v<=max; всегда valid; всегда invalid. Для каждого верните true, если хотя бы один values отличает мутанта от правильного min<=v<=max.','Объект {min:целое,max:целое,values:[целое]}, min<=max.','Массив четырёх boolean в указанном порядке.',ranges,x=>[x.values.some(v=>v===x.min),x.values.some(v=>v===x.max),x.values.some(v=>v<x.min||v>x.max),x.values.some(v=>v>=x.min&&v<=x.max)],'[any(v==data["min"] for v in data["values"]),any(v==data["max"] for v in data["values"]),any(not data["min"]<=v<=data["max"] for v in data["values"]),any(data["min"]<=v<=data["max"] for v in data["values"])]',null,1);
pp('test-design','state-machine-invalid-events',3,'Заказ начинается в new. pay: new->paid; ship: paid->shipped; cancel: new/paid->cancelled. Другие переходы запрещены и состояние не меняют. Верните state и индексы запрещённых событий.','Массив "pay"|"ship"|"cancel".','Объект {state,invalid}.',[[],['ship'],['pay','ship','cancel'],['pay','cancel','pay'],['cancel','ship']],a=>{let state='new';const invalid=[];a.forEach((e,i)=>{if(e==='pay'&&state==='new')state='paid';else if(e==='ship'&&state==='paid')state='shipped';else if(e==='cancel'&&['new','paid'].includes(state))state='cancelled';else invalid.push(i);});return {state,invalid};},'state="new"; invalid=[]\nfor i,e in enumerate(data):\n    if e=="pay" and state=="new": state="paid"\n    elif e=="ship" and state=="paid": state="shipped"\n    elif e=="cancel" and state in ("new","paid"): state="cancelled"\n    else: invalid.append(i)\nprint(json.dumps({"state":state,"invalid":invalid}))',null,0);
