definitions['ml-engineering'].find(x=>x.id==='batch-resource-packing').source='import json,sys\ndata=json.load(sys.stdin)\nbatches=[]; current=[]; size=0\nfor r in data:\n    if current and size+len(r["features"])>4:\n        batches.append(current); current=[]; size=0\n    current.append(r["id"]); size+=len(r["features"])\n    if size>4:\n        batches.append(current); current=[]; size=0\nif current: batches.append(current)\nprint(json.dumps(batches))';

