definitions['test-design'].find(t=>t.id==='risk-budget-maximization').oracle=a=>{let best=[],score=0;const less=(a,b)=>{for(let i=0;i<Math.min(a.length,b.length);i++)if(a[i]!==b[i])return a[i]<b[i];return a.length<b.length;};for(let mask=0;mask<2**a.length;mask++){const r=a.filter((_,i)=>mask&(1<<i));if(sum(r.map(x=>x.cost))>3)continue;const s=sum(r.map(x=>x.probability*x.impact)),ids=r.map(x=>x.id).sort();if(s>score||s===score&&less(ids,best)){best=ids;score=s;}}return best;};
definitions.python.find(t=>t.id==='multiset-subtraction').source='import json,sys,collections\ndata=json.load(sys.stdin)\ncounts=collections.Counter(data["b"])\nresult=[]\nfor x in data["a"]:\n    if counts[x]>0: counts[x]-=1\n    else: result.append(x)\nprint(json.dumps(result))';
// The old bank already counts covered pairs. This task instead selects a suite.
const pairwise=definitions['test-design'].find(t=>t.id==='pairwise-missing-combinations');
pairwise.id='greedy-pairwise-selection';
pairwise.prompt='Жадно выберите набор cases для pairwise-покрытия трёх boolean-факторов active,admin,paid. Начните без покрытых пар. Каждый шаг выберите ещё не выбранный case, добавляющий больше всего новых пар (индекс фактора,значение; индекс другого фактора,значение). При равенстве — меньший входной индекс. Остановитесь при нулевом приросте. Верните индексы в порядке выбора.';
pairwise.input='Массив не более 20 объектов {active:boolean,admin:boolean,paid:boolean}.';
const keys=r=>{const v=[r.active,r.admin,r.paid];return [String([0,v[0],1,v[1]]),String([0,v[0],2,v[2]]),String([1,v[1],2,v[2]])];};
pairwise.oracle=a=>{const covered=new Set(),selected=[];while(true){let best=-1,gain=0;for(let i=0;i<a.length;i++){if(selected.includes(i))continue;const n=keys(a[i]).filter(k=>!covered.has(k)).length;if(n>gain){gain=n;best=i;}}if(best<0)return selected;selected.push(best);keys(a[best]).forEach(k=>covered.add(k));}};
pairwise.source='import json,sys,itertools\ndata=json.load(sys.stdin)\npairs=[]\nfor r in data:\n    v=[r["active"],r["admin"],r["paid"]]\n    pairs.append({(i,v[i],j,v[j]) for i,j in itertools.combinations(range(3),2)})\ncovered=set(); selected=[]\nwhile True:\n    choices=[(len(p-covered),-i,i) for i,p in enumerate(pairs) if i not in selected]\n    if not choices: break\n    gain,_,i=max(choices)\n    if not gain: break\n    selected.append(i); covered.update(pairs[i])\nprint(json.dumps(selected))';
